package com.abyssredemption.abstool.client.serverstats.network.payload;
import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.network.codec.StreamCodec; import net.minecraft.network.protocol.common.custom.CustomPacketPayload; import net.minecraft.resources.Identifier;
public record StatsErrorPayload(int protocolVersion,long requestId,int errorCode,String message) implements CustomPacketPayload { public static final Type<StatsErrorPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath("absservertool","stats_error")); public static final StreamCodec<RegistryFriendlyByteBuf,StatsErrorPayload> CODEC=StreamCodec.of((b,p)->{b.writeVarInt(p.protocolVersion);b.writeVarLong(p.requestId);b.writeVarInt(p.errorCode);b.writeUtf(p.message,256);},b->new StatsErrorPayload(b.readVarInt(),b.readVarLong(),b.readVarInt(),b.readUtf(256))); public Type<? extends CustomPacketPayload> type(){return TYPE;} }
